"""Triton ``multilabel_margin_loss_backward``.

Contract, established by target-side probes of
``aten::multilabel_margin_loss_backward`` (geometry, grad_output broadcasting,
the roles of ``target`` versus ``is_target``, dtype acceptance, non-contiguous
strides) and by the frozen FlagGems pytest of the forward pass:

* ``self`` is an (N, C) float matrix, or a rank<=1 single C-class row; ``target``
  is int64 of exactly the same shape, listing active class ids terminated by the
  first ``-1``; ``is_target`` is the forward's float membership mask, of the same
  shape and dtype as ``self``.
* Per row, with ``A`` the active target prefix (duplicates kept, entries behind
  the first ``-1`` ignored) and ``NT`` the classes whose ``is_target`` entry is
  zero, the forward row loss is
  ``(1/C) * sum_{j in A} sum_{d in NT} relu(1 - x[target[j]] + x[d])``.
  Differentiating that sum gives, for a class ``a``, with
  ``mult[a] = #{j in A : target[j] == a}``::

      g[a] = mult[a] * ( -#{d in NT : 1 - x[a] + x[d] > 0} )          # a in A
      g[d] +=  sum_{a in A} mult[a] * [1 - x[a] + x[d] > 0]           # d in NT

  scaled by ``1/C``, by a further ``1/N`` for the mean reduction, and by
  ``grad_output``.  Probed against the native kernel: the ``mult`` weight applies
  to *both* terms, so a target prefix that repeats a class id scales its whole
  gradient row accordingly.
* The reference for the formula above is the native *CPU* kernel, which
  implements it for every input.  Probed on the measured target: the native CUDA
  backward drops the gradient of the last active target of a row, writing a plain
  zero into that column, once the active prefix is longer than 32 and its length
  is not a multiple of the 32-wide reduction it folds the target axis with.  The
  deviation is deterministic, reproduces over a (class count x prefix length)
  grid, and is backward-only -- the forward loss and ``is_target`` agree across
  backends for the same inputs -- so this module follows the CPU values.
* ``target`` and ``is_target`` play distinct roles and are not interchangeable:
  the multiplicity comes from ``target`` while the non-target set comes from
  ``is_target``.  Probed by perturbing one against the other -- marking a class
  in ``is_target`` that ``target`` does not list, and clearing one that it does,
  both change the native result exactly as the split above predicts.
* ``grad_output`` is per-row (shape ``(N,)``) for reduction 0 and a scalar for
  the mean and sum reductions; a 1-D ``grad_output`` of any other length is
  rejected at reduction 0 rather than broadcast.  A 0-dim value is applied to
  every row, which is what the CPU kernel documents and does -- the native CUDA
  kernel instead indexes grad_output per row whatever its size, so for a 0-dim
  argument it reads past the one element it was given (probed by varying the
  memory behind such a buffer: rows 1.. of its result follow that padding).
  Broadcasting is the defined behaviour, so it is what this module implements.
  Reductions other than 0/1/2 are treated as sum, matching the native kernel.
* The result has the shape, dtype and layout of ``self``; a rank<=1 input keeps
  its rank, and ``N == 0`` produces an empty result without launching.
* Non-contiguous strided inputs are handled through explicit strides.

The gradient accumulates over an (a, d) class pair tile per row, so the pairs of
one row are produced by a single program and the ``is_target`` mask is read once
per tile.  All numerical work happens in the Triton kernels; the host wrapper only
does metadata math, allocation and launches.
"""

import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn

logger = logging.getLogger(__name__)

_SUPPORTED_INPUT_DTYPES = (
    torch.float16,
    torch.bfloat16,
    torch.float32,
    torch.float64,
)

# Target ids are scanned a tile at a time purely to find the first -1, so this
# only needs to be wide enough to amortise the loop; 256 matches the forward.
_BLOCK_T = 256
# The gradient is an (own class, other class) pair tile. The candidate widths are
# tried largest-first so a wide class axis keeps the tile square and a narrow one
# still spreads over enough programs; 32 is the smallest that keeps a tile at or
# above one warp per row of the pair.
_GRAD_BLOCK_CANDIDATES = (128, 64, 32)
# Below this many programs the grid cannot cover the device, so a narrower tile
# is preferred even though it loads the other-class operand more times.
_MIN_GRAD_PROGRAMS = 512


@triton.jit
def _membership_kernel(
    t_ptr,
    m_ptr,
    C,
    trs,
    tcs,
    BLOCK_T: tl.constexpr,
):
    """Multiplicity of every class id inside the active target prefix of a row.

    ``is_target`` only records *whether* a class is active, so the per-id counts
    the gradient weights both of its terms by are recovered from ``target`` here.
    """
    row = tl.program_id(0)
    bt = row * trs
    stop = C
    for t0 in range(0, C, BLOCK_T):
        offs = t0 + tl.arange(0, BLOCK_T)
        m = offs < C
        tb = tl.load(t_ptr + bt + offs * tcs, mask=m, other=-1)
        stop = tl.minimum(stop, tl.min(tl.where(m & (tb < 0), offs, C), axis=0))
    for c0 in range(0, C, BLOCK_T):
        offs = c0 + tl.arange(0, BLOCK_T)
        cm = offs < C
        cnt = tl.zeros((BLOCK_T,), dtype=tl.int32)
        for t0 in range(0, stop, BLOCK_T):
            jj = t0 + tl.arange(0, BLOCK_T)
            jm = jj < stop
            # -2 can never equal a class offset, so masked-off lanes contribute
            # nothing to the count.
            ids = tl.load(t_ptr + bt + jj * tcs, mask=jm, other=-2)
            cnt += tl.sum(
                ((ids[:, None] == offs[None, :]) & jm[:, None]).to(tl.int32), axis=0
            )
        tl.store(m_ptr + row * C + offs, cnt, mask=cm)


@triton.jit
def _grad_kernel(
    x_ptr,
    m_ptr,
    it_ptr,
    g_ptr,
    go_ptr,
    C,
    srs,
    scs,
    irs,
    ics,
    scale,
    PER_ROW_GRAD: tl.constexpr,
    ACC64: tl.constexpr,
    BLOCK: tl.constexpr,
):
    """d(loss)/dx for one (row, class tile) pair (see the module docstring).

    Each program owns one tile of the class axis and produces that tile's final
    values, so a few-row / large-C shape still fills the device and the result is
    written once per class instead of accumulated through atomics.  Both gradient
    terms of a class are sums over the *whole* class axis, so the other operand is
    streamed tile by tile: the own-class term needs the surviving pairs where the
    own class is an active target, and the other-class term needs those where it
    is the non-target partner.  One pass over the other axis yields both.
    """
    row = tl.program_id(0)
    tile = tl.program_id(1)
    bx = row * srs
    bi = row * irs
    rb = row * C
    if PER_ROW_GRAD:
        factor = tl.load(go_ptr + row)
    else:
        factor = tl.load(go_ptr)
    if ACC64:
        factor = factor.to(tl.float64)
    else:
        factor = factor.to(tl.float32)
    weight = scale * factor

    offs = tile * BLOCK + tl.arange(0, BLOCK)
    mask = offs < C
    mult = tl.load(m_ptr + rb + offs, mask=mask, other=0)
    is_target_own = mult > 0
    # ``other=1.0`` marks padding lanes as targets, so they never enter the
    # non-target set of either term.
    it_own = tl.load(it_ptr + bi + offs * ics, mask=mask, other=1.0)
    non_target_own = mask & (it_own == 0.0)
    x_own = tl.load(x_ptr + bx + offs * scs, mask=mask, other=0.0)
    if ACC64:
        acc = tl.zeros((BLOCK,), dtype=tl.float64)
        mult_own = mult.to(tl.float64)
    else:
        acc = tl.zeros((BLOCK,), dtype=tl.float32)
        mult_own = mult.to(tl.float32)

    # A tile holding no active target contributes nothing to the first term, and
    # one holding no non-target class nothing to the second, whatever the other
    # operand is; checking once here keeps the whole pair outer product out of
    # the loop for the all-target and empty-prefix rows.
    any_own_target = tl.sum(is_target_own.to(tl.int32), axis=0) != 0
    any_own_non_target = tl.sum(non_target_own.to(tl.int32), axis=0) != 0

    if any_own_target or any_own_non_target:
        for other0 in range(0, C, BLOCK):
            offs_other = other0 + tl.arange(0, BLOCK)
            mask_other = offs_other < C
            mult_other = tl.load(m_ptr + rb + offs_other, mask=mask_other, other=0)
            it_other = tl.load(
                it_ptr + bi + offs_other * ics, mask=mask_other, other=1.0
            )
            non_target_other = mask_other & (it_other == 0.0)
            is_target_other = mult_other > 0
            # The streamed tile pairs with the own tile through the first term
            # only where it holds a non-target class, and through the second only
            # where it holds an active target. A tile that offers neither is
            # skipped before its operand is even read.
            need_first = any_own_target and (
                tl.sum(non_target_other.to(tl.int32), axis=0) != 0
            )
            need_second = any_own_non_target and (
                tl.sum(is_target_other.to(tl.int32), axis=0) != 0
            )
            if need_first or need_second:
                x_other = tl.load(
                    x_ptr + bx + offs_other * scs, mask=mask_other, other=0.0
                )
                if need_first:
                    # Pairs with the own class as the active target and the other
                    # class as the non-target partner. Hinge in the input element
                    # type, exactly as the native kernel.
                    hinge_own = ((1.0 - x_own)[:, None] + x_other[None, :]) > 0.0
                    own_as_target = (
                        hinge_own & is_target_own[:, None] & non_target_other[None, :]
                    )
                    acc -= tl.sum(
                        tl.where(own_as_target, mult_own[:, None], 0.0), axis=1
                    )
                if need_second:
                    # The mirrored set: the other class is the active target and
                    # the own class is the non-target partner.
                    if ACC64:
                        mult_other_w = mult_other.to(tl.float64)
                    else:
                        mult_other_w = mult_other.to(tl.float32)
                    hinge_other = ((1.0 - x_other)[:, None] + x_own[None, :]) > 0.0
                    own_as_non_target = (
                        hinge_other & is_target_other[:, None] & non_target_own[None, :]
                    )
                    acc += tl.sum(
                        tl.where(own_as_non_target, mult_other_w[:, None], 0.0),
                        axis=0,
                    )

    tl.store(g_ptr + rb + offs, acc * weight, mask=mask)


def _grad_block_for(rows, n_classes):
    """Class-tile width for the gradient grid.

    The grid is (rows, class tiles), so a wide tile means fewer programs. The
    widest candidate is taken as long as it still leaves enough programs to cover
    the device; otherwise a narrower one trades repeated loads of the streamed
    operand for parallelism, which is what the few-row benchmark shapes need.
    """
    for block in _GRAD_BLOCK_CANDIDATES:
        tiles = -(-n_classes // block)
        if rows * tiles >= _MIN_GRAD_PROGRAMS:
            return block
    smallest = _GRAD_BLOCK_CANDIDATES[-1]
    # A class axis narrower than the smallest tile cannot be split further, so
    # the tile shrinks to its power-of-two width instead.
    if n_classes < smallest:
        return max(16, triton.next_power_of_2(n_classes))
    return smallest


def _strides2d(t):
    """(row_stride, class_stride) for a rank<=2 tensor viewed as (rows, classes)."""
    if t.dim() == 0:
        return 1, 1
    if t.dim() == 1:
        return 0, t.stride(0)
    return t.stride(0), t.stride(1)


def _row_col(t):
    if t.dim() == 0:
        return 1, 1
    if t.dim() == 1:
        return 1, int(t.shape[0])
    return int(t.shape[0]), int(t.shape[1])


def _check_inputs(grad_output, self, target, is_target):
    if self.dim() > 2:
        raise RuntimeError(
            "multilabel_margin_loss_backward: input must be scalar, 1D or 2D"
        )
    if tuple(self.shape) != tuple(target.shape):
        raise RuntimeError(
            "multilabel_margin_loss_backward: target shape must exactly match "
            "input shape"
        )
    if tuple(self.shape) != tuple(is_target.shape):
        raise RuntimeError(
            "multilabel_margin_loss_backward: is_target shape must exactly match "
            "input shape"
        )
    if self.device != target.device or self.device != is_target.device:
        raise RuntimeError(
            "multilabel_margin_loss_backward: input, target and is_target must be "
            "on the same device"
        )
    if grad_output.device != self.device:
        raise RuntimeError(
            "multilabel_margin_loss_backward: grad_output must be on the same "
            "device as input"
        )
    if target.dtype != torch.int64:
        raise RuntimeError(
            "multilabel_margin_loss_backward: target must have dtype torch.int64"
        )
    if self.dtype not in _SUPPORTED_INPUT_DTYPES:
        raise RuntimeError(
            "multilabel_margin_loss_backward: input must have a floating-point "
            "loss dtype"
        )
    if is_target.dtype != self.dtype:
        raise RuntimeError(
            "multilabel_margin_loss_backward: is_target must have the same dtype "
            "as input"
        )

    rows, n_classes = _row_col(self)
    if n_classes == 0:
        raise RuntimeError(
            "multilabel_margin_loss_backward: class dimension must be non-empty"
        )
    return rows, n_classes


def multilabel_margin_loss_backward(
    grad_output: torch.Tensor,
    self: torch.Tensor,
    target: torch.Tensor,
    reduction: int,
    is_target: torch.Tensor,
):
    logger.debug("GEMS MULTILABEL_MARGIN_LOSS_BACKWARD")
    if isinstance(reduction, bool) or not isinstance(reduction, int):
        raise RuntimeError(
            "multilabel_margin_loss_backward: reduction must be an integer "
            "(0, 1 or 2)"
        )
    if reduction not in (0, 1, 2):
        # The native kernel maps every other integer to "sum".
        reduction = 2

    rows, n_classes = _check_inputs(grad_output, self, target, is_target)
    if rows == 0:
        return torch.empty_like(self)

    # grad_output is per-row only for reduction 0; the scalar reductions get one
    # value. Probed on the native kernel: reduction 0 takes either a 0-dim value,
    # applied to every row, or a 1-D tensor of exactly ``rows`` entries -- a 1-D
    # tensor of any other length is rejected rather than broadcast.
    if reduction == 0 and grad_output.dim() >= 1 and grad_output.numel() != rows:
        raise RuntimeError(
            "multilabel_margin_loss_backward: grad_output must hold one value per "
            "row for reduction 0"
        )
    # Indexing per row is only safe once grad_output really carries one value per
    # row; a 0-dim value is read from the base pointer and broadcast instead.
    per_row_grad = reduction == 0 and grad_output.dim() >= 1 and rows > 1
    grad_output = grad_output.contiguous()

    acc64 = self.dtype == torch.float64
    srs, scs = _strides2d(self)
    trs, tcs = _strides2d(target)
    irs, ics = _strides2d(is_target)

    scale = 1.0 / float(n_classes)
    if reduction == 1:
        scale /= float(rows)

    with torch_device_fn.device(self.device):
        mult = torch.empty((rows, n_classes), dtype=torch.int32, device=self.device)
        _membership_kernel[(rows,)](
            target,
            mult,
            n_classes,
            trs,
            tcs,
            BLOCK_T=_BLOCK_T,
        )
        # Every class is written exactly once, by the program owning its tile,
        # so the accumulator needs no pre-zeroing; it is a dense fp32/fp64 buffer
        # rounded to the input dtype once at the end.
        grad_input = torch.empty(
            (rows, n_classes),
            dtype=torch.float64 if acc64 else torch.float32,
            device=self.device,
        )
        block = _grad_block_for(rows, n_classes)
        _grad_kernel[(rows, triton.cdiv(n_classes, block))](
            self,
            mult,
            is_target,
            grad_input,
            grad_output,
            n_classes,
            srs,
            scs,
            irs,
            ics,
            scale,
            PER_ROW_GRAD=per_row_grad,
            ACC64=acc64,
            BLOCK=block,
        )
    return grad_input.to(self.dtype).reshape(self.shape)
